                    "price_low": gap_low,
                    "price_midpoint": (gap_high + gap_low) / 2,
                    "metadata": {
                        "classification": "BISI",
                        "displacement_bar": bars[i - 1].timestamp.isoformat(),
                    },
                })
            elif a.low > c.high:
                gap_high, gap_low = a.low, c.high
                events.append({
                    "event_type": "fvg",
