from app.ict.base import BarData, BaseDetector


class SwingDetector(BaseDetector):
    def __init__(self, n: int = 3):
        self.n = n

    def detect(self, bars: list[BarData]) -> list[dict]:
        events, _ = self._run(bars)
        return events

    def detect_with_index(self, bars: list[BarData]) -> tuple[list[dict], dict]:
        """Returns (events, pivot_index -> event) for downstream detectors."""
        return self._run(bars)

    def _run(self, bars: list[BarData]) -> tuple[list[dict], dict]:
        n = self.n
        events: list[dict] = []
        index_map: dict[int, dict] = {}

        for i in range(n, len(bars) - n):
            bar = bars[i]
            prev_highs = [bars[j].high for j in range(i - n, i)]
            next_highs = [bars[j].high for j in range(i + 1, i + n + 1)]
            prev_lows = [bars[j].low for j in range(i - n, i)]
            next_lows = [bars[j].low for j in range(i + 1, i + n + 1)]

            if bar.high > max(prev_highs) and bar.high > max(next_highs):
                event = {
                    "event_type": "swing_high",
                    "timestamp": bars[i + n].timestamp,
                    "instrument": bar.instrument,
                    "timeframe": bar.timeframe,
                    "direction": "neutral",
                    "price_high": bar.high,
                    "price_low": bar.high,
                    "price_midpoint": bar.high,
                    "metadata": {
                        "pivot_price": bar.high,
                        "pivot_index": i,
                        "lookback": n,
                    },
                }
                events.append(event)
                index_map[i] = event

            elif bar.low < min(prev_lows) and bar.low < min(next_lows):
                event = {
                    "event_type": "swing_low",
                    "timestamp": bars[i + n].timestamp,
                    "instrument": bar.instrument,
                    "timeframe": bar.timeframe,
                    "direction": "neutral",
                    "price_high": bar.low,
                    "price_low": bar.low,
                    "price_midpoint": bar.low,
                    "metadata": {
                        "pivot_price": bar.low,
                        "pivot_index": i,
                        "lookback": n,
                    },
                }
                events.append(event)
                index_map[i] = event

        return events, index_map

