from app.ict.base import BarData, BaseDetector

_SESSIONS: dict[str, tuple[int, int]] = {
    "asia": (1, 5),
    "london": (7, 10),
    "ny_am": (13, 16),
    "ny_pm": (18, 21),
}


class SessionDetector(BaseDetector):
    def detect(self, bars: list[BarData]) -> list[dict]:
        events: list[dict] = []
        seen: set[tuple] = set()
        active: dict[str, bool] = {s: False for s in _SESSIONS}

        for bar in bars:
            hour = bar.timestamp.hour
            day = bar.timestamp.date()

            for session, (start_h, end_h) in _SESSIONS.items():
                in_now = start_h <= hour < end_h
                was_in = active[session]

                if in_now and not was_in:
                    key = (day, session, "open")
                    if key not in seen:
                        seen.add(key)
                        events.append({
                            "event_type": "session_open",
                            "timestamp": bar.timestamp,
                            "instrument": bar.instrument,
                            "timeframe": bar.timeframe,
                            "direction": "neutral",
                            "price_high": bar.open,
                            "price_low": bar.open,
                            "price_midpoint": bar.open,
                            "metadata": {"session": session},
                        })

                elif not in_now and was_in:
                    key = (day, session, "close")
                    if key not in seen:
                        seen.add(key)
                        events.append({
                            "event_type": "session_close",
                            "timestamp": bar.timestamp,
                            "instrument": bar.instrument,
                            "timeframe": bar.timeframe,
                            "direction": "neutral",
                            "price_high": bar.close,
                            "price_low": bar.close,
                            "price_midpoint": bar.close,
                            "metadata": {"session": session},
                        })

                active[session] = in_now

        return events

