from app.ict.base import BarData, BaseDetector
from app.ict.detectors.swing import SwingDetector


class LiquiditySweepDetector(BaseDetector):
    def __init__(self, tolerance: float = 2.0, swing_n: int = 3):
        self.tolerance = tolerance
        self.swing_n = swing_n
        self._swing = SwingDetector(n=swing_n)

    def detect(self, bars: list[BarData]) -> list[dict]:
        events: list[dict] = []
        swing_events, _ = self._swing.detect_with_index(bars)

        highs = [e["price_high"] for e in swing_events if e["event_type"] == "swing_high"]
        lows = [e["price_low"] for e in swing_events if e["event_type"] == "swing_low"]

        bsl_levels = self._clusters(highs)
        ssl_levels = self._clusters(lows)

        for bar in bars:
            for level in bsl_levels:
                if bar.high > level and bar.close < level:
                    events.append({
                        "event_type": "sweep",
                        "timestamp": bar.timestamp,
                        "instrument": bar.instrument,
                        "timeframe": bar.timeframe,
                        "direction": "bearish",
                        "price_high": bar.high,
                        "price_low": bar.low,
                        "price_midpoint": level,
                        "metadata": {
                            "liquidity_type": "bsl",
                            "equal_level": level,
                            "num_equal_points": sum(
                                1 for h in highs if abs(h - level) <= self.tolerance
                            ),
                        },
                    })
            for level in ssl_levels:
                if bar.low < level and bar.close > level:
                    events.append({
                        "event_type": "sweep",
                        "timestamp": bar.timestamp,
                        "instrument": bar.instrument,
                        "timeframe": bar.timeframe,
                        "direction": "bullish",
                        "price_high": bar.high,
                        "price_low": bar.low,
                        "price_midpoint": level,
                        "metadata": {
                            "liquidity_type": "ssl",
                            "equal_level": level,
                            "num_equal_points": sum(
                                1 for lo in lows if abs(lo - level) <= self.tolerance
                            ),
                        },
                    })
        return events

    def _clusters(self, prices: list[float]) -> list[float]:
        if not prices:
            return []
        clusters: list[float] = []
        for p in prices:
            matched = False
            for existing in clusters:
                if abs(p - existing) <= self.tolerance:
                    matched = True
                    break
            if not matched:
                # Check if any other price is within tolerance (need ≥2 to form cluster)
                cluster_members = [x for x in prices if abs(x - p) <= self.tolerance]
                if len(cluster_members) >= 2:
                    clusters.append(sum(cluster_members) / len(cluster_members))
        return clusters

