from app.ict.detectors.swing import SwingDetector


class MarketStructureDetector(BaseDetector):
    def __init__(self, swing_n: int = 3):
        self.swing_n = swing_n
        self._swing = SwingDetector(n=swing_n)

    def detect(self, bars: list[BarData]) -> list[dict]:
        swing_events, index_map = self._swing.detect_with_index(bars)
        if not swing_events:
            return []

        events: list[dict] = []
        trend = "unknown"
        swing_highs: list[tuple[float, object, int]] = []  # (price, ts, bar_idx)
        swing_lows: list[tuple[float, object, int]] = []

        ordered = sorted(swing_events, key=lambda e: e["metadata"]["pivot_index"])

        for swing in ordered:
            stype = swing["event_type"]
            price = swing["price_high"]
            idx = swing["metadata"]["pivot_index"]
            ts = swing["timestamp"]
            bar = bars[idx]

            if stype == "swing_high":
                if swing_highs and price > swing_highs[-1][0]:
                    if trend == "bearish":
                        events.append(self._evt("choch", "bullish", ts, bar, swing_highs[-1]))
                        trend = "bullish"
                    elif trend == "bullish":
                        events.append(self._evt("bos", "bullish", ts, bar, swing_highs[-1]))
                    else:
                        trend = "bullish"
                elif not swing_highs:
                    trend = "bullish" if trend == "unknown" else trend
                swing_highs.append((price, ts, idx))

            elif stype == "swing_low":
                if swing_lows and price < swing_lows[-1][0]:
                    if trend == "bullish":
                        events.append(self._evt("choch", "bearish", ts, bar, swing_lows[-1]))
                        trend = "bearish"
                    elif trend == "bearish":
                        events.append(self._evt("bos", "bearish", ts, bar, swing_lows[-1]))
                    else:
                        trend = "bearish"
                elif not swing_lows:
                    trend = "bearish" if trend == "unknown" else trend
                swing_lows.append((price, ts, idx))

        return events

    def _evt(
        self,
        event_type: str,
        direction: str,
        ts,
        bar: BarData,
        broken_swing: tuple,
    ) -> dict:
        return {
            "event_type": event_type,
            "timestamp": ts,
            "instrument": bar.instrument,
            "timeframe": bar.timeframe,
            "direction": direction,
            "price_high": bar.high,
            "price_low": bar.low,
            "price_midpoint": (bar.high + bar.low) / 2,
            "metadata": {
                "broken_swing_ts": broken_swing[1].isoformat(),
                "swing_price": broken_swing[0],
                "trend_before": "bearish" if direction == "bullish" else "bullish",
            },
        }

